.75rem; padding-bottom: .55rem; border-bottom: 1px solid rgba(86,112,79,.14); }.compact-list span { overflow: hidden; color: #50634d; text-overflow: ellipsis; white-space: nowrap; }.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; }@media (max-width: 48rem) { .cookbook-hero { align-items: flex-start; flex-direction: column; }.home-grid { grid-template-columns: 1fr; } }@media (max-width: 36rem) { .hero-actions { flex-wrap: wrap; }.recipe-grid { grid-template-columns: 1fr; } }
</style>
